<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}"><title>Haman Planner</title>
<style>
:root{--bg:#f4f6f9;--card:#fff;--ink:#172033;--muted:#718096;--line:#e4e8ef;--nav:#0f1726;--nav2:#1e2a3d;--blue:#3157d5;--ok:#087f5b;--warn:#9a6509;--danger:#b42318}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}
.shell{display:grid;grid-template-columns:255px 1fr;min-height:100vh}.side{background:var(--nav);color:#fff;padding:20px 14px;position:sticky;top:0;height:100vh;overflow:auto}.brand{font-size:21px;font-weight:900;padding:7px 10px 22px}.brand small{display:block;font-size:10px;color:#8d9ab0;margin-top:5px;font-weight:500}.nav{display:grid;gap:3px}.group{font-size:10px;color:#65738a;margin:16px 10px 5px}.nav button,.bottom button{border:0;background:transparent;color:#b8c3d4;text-align:right;border-radius:9px;padding:10px 11px;width:100%}.nav button:hover,.nav button.active{background:var(--nav2);color:#fff}.bottom{border-top:1px solid #273247;margin-top:18px;padding-top:12px}.main{min-width:0;padding:28px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:20px}.eyebrow{font-size:11px;color:var(--muted)}h1{font-size:29px;margin:4px 0;font-weight:900}.actions{display:flex;gap:7px}.btn{border:1px solid #d4dbe5;background:#fff;color:var(--ink);border-radius:10px;padding:9px 13px;font-weight:700}.btn.primary{background:var(--ink);color:#fff;border-color:var(--ink)}.btn.danger{color:var(--danger)}.btn.small{font-size:11px;padding:6px 9px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:var(--card);border:1px solid var(--line);border-radius:15px;padding:17px;box-shadow:0 3px 15px rgba(16,24,39,.035)}.metric{font-size:27px;font-weight:900;margin-top:5px}.muted{color:var(--muted);font-size:12px}.grid2{display:grid;grid-template-columns:1.5fr 1fr;gap:13px;margin-top:13px}.section{margin-top:13px}.head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.head h2{font-size:16px;margin:0}.list{display:grid;gap:7px}.row{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid var(--line);border-radius:10px;padding:11px;background:#fff}.rowmain{min-width:0}.rowtitle{font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.rowsub{font-size:11px;color:var(--muted);margin-top:3px}.rowactions{display:flex;gap:4px;flex-shrink:0}.pill{display:inline-block;border-radius:999px;padding:4px 8px;background:#edf1f6;font-size:10px;white-space:nowrap}.pill.ok{background:#e9f8f2;color:var(--ok)}.pill.warn{background:#fff6df;color:var(--warn)}.pill.danger{background:#fff0ef;color:var(--danger)}.progress{height:6px;background:#edf0f4;border-radius:20px;overflow:hidden;margin-top:7px}.progress i{display:block;height:100%;background:var(--ink)}.toolbar{display:flex;gap:8px;justify-content:space-between;align-items:center;margin-bottom:10px}.search{width:min(390px,100%);border:1px solid #d6dce5;border-radius:10px;padding:9px 11px}.filters{display:flex;gap:6px;flex-wrap:wrap}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid var(--line);font-size:12px;text-align:right}.table th{font-size:10px;color:var(--muted)}.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.day{min-height:145px;border:1px solid var(--line);border-radius:11px;background:#fff;padding:9px}.block{background:#eef2ff;border-radius:7px;padding:6px;margin-top:6px;font-size:10px}.modalback{position:fixed;inset:0;background:#11182799;display:none;align-items:center;justify-content:center;padding:20px;z-index:99}.modalback.show{display:flex}.modal{width:min(760px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:22px}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.field.full{grid-column:1/-1}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:9px;border:1px solid #d6dce5;border-radius:9px;background:#fff}.field textarea{min-height:90px}.modalactions{display:flex;gap:7px;margin-top:15px}.toast{position:fixed;bottom:20px;left:20px;background:#172033;color:#fff;padding:11px 14px;border-radius:9px;display:none;z-index:120}.toast.show{display:block}.empty{text-align:center;color:#8a95a5;padding:28px}.statgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.hide{display:none!important}@media(max-width:1050px){.shell{grid-template-columns:80px 1fr}.brand span,.brand small,.nav .txt,.group,.bottom .txt{display:none}.brand{text-align:center}.nav button,.bottom button{text-align:center}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.shell{display:block}.side{height:auto;position:sticky;z-index:20;padding:8px;display:flex;overflow:auto}.brand{padding:9px}.nav{display:flex}.nav button{white-space:nowrap}.bottom{display:none}.main{padding:14px}.top{flex-direction:column}.cards,.grid2,.formgrid,.statgrid{grid-template-columns:1fr}.calendar{grid-template-columns:1fr 1fr}}
</style></head>
<body>
<div class="shell"><aside class="side">
<div class="brand"><span>Haman Planner</span><small>Personal & Business Operating System</small></div>
<nav class="nav">
<button class="active" data-view="today">◉ <span class="txt">امروز</span></button><button data-view="tasks">✓ <span class="txt">کارها</span></button><button data-view="inbox">▣ <span class="txt">Inbox</span></button><button data-view="search">⌕ <span class="txt">جستجو</span></button>
<div class="group">ساختار</div><button data-view="areas">◈ <span class="txt">حوزه‌ها</span></button><button data-view="goals">◎ <span class="txt">اهداف</span></button><button data-view="projects">▤ <span class="txt">پروژه‌ها</span></button><button data-view="milestones">◇ <span class="txt">Milestones</span></button>
<div class="group">اجرا</div><button data-view="daily">☀ <span class="txt">Daily Plan</span></button><button data-view="calendar">□ <span class="txt">تقویم</span></button><button data-view="execution">◷ <span class="txt">Execution</span></button><button data-view="dependencies">⇄ <span class="txt">Dependencies</span></button><button data-view="reminders">◌ <span class="txt">یادآورها</span></button><button data-view="failures">⚠ <span class="txt">Failure Reasons</span></button>
<div class="group">تحلیل</div><button data-view="reviews">↻ <span class="txt">Reviews</span></button><button data-view="analytics">◫ <span class="txt">Analytics</span></button><button data-view="reports">▥ <span class="txt">Reports</span></button>
<div class="group">دانش و AI</div><button data-view="notes">▤ <span class="txt">Notes</span></button><button data-view="decisions">◆ <span class="txt">Decisions</span></button><button data-view="ai-planner">✦ <span class="txt">AI Planner</span></button><button data-view="ai">✧ <span class="txt">AI Interactions</span></button><button data-view="pending">⌛ <span class="txt">Pending Actions</span></button><button data-view="activity">◌ <span class="txt">Activity Logs</span></button>
</nav>
<div class="bottom"><button onclick="location.href='/admin/users'">⚙ <span class="txt">مدیریت</span></button><form method="post" action="{{route('logout')}}">@csrf<button>↪ <span class="txt">خروج</span></button></form></div>
</aside>
<main class="main"><div class="top"><div><div class="eyebrow">Haman Planner · {{auth()->user()->name}} · {{auth()->user()->email}}</div><h1 id="title">امروز</h1></div><div class="actions"><button class="btn" onclick="loadView(view)">↻ بروزرسانی</button><button class="btn primary" onclick="openCreate()">＋ افزودن</button></div></div><div id="content"></div></main></div>
<div class="modalback" id="modal"><div class="modal"><div class="head"><h2 id="mtitle">افزودن</h2><button class="btn small" onclick="closeModal()">×</button></div><div id="mbody"></div></div></div><div id="toast" class="toast"></div>
<script>
const csrf=document.querySelector('meta[name=csrf-token]').content,$=id=>document.getElementById(id);let view='today',cache={areas:[],goals:[],projects:[],milestones:[],tasks:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmt=v=>v?new Date(v).toLocaleDateString('fa-IR'):'—',fmtDT=v=>v?new Date(v).toLocaleString('fa-IR',{dateStyle:'short',timeStyle:'short'}):'—';
function toast(m){$('toast').textContent=m;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
async function api(path,opt={}){let method=(opt.method||'GET').toUpperCase(),h={'Accept':'application/json','X-CSRF-TOKEN':csrf,...(opt.headers||{})};if(method!=='GET'&&method!=='HEAD')h['Content-Type']='application/json';let r=await fetch('/api'+path,{credentials:'same-origin',...opt,headers:h});if(r.status===401){location='/login';throw Error('نشست شما منقضی شده است')}if(!r.ok){let x={};try{x=await r.json()}catch{}throw Error(x.message||Object.values(x.errors||{}).flat().join(' ')||'خطا');}return r.status===204?null:r.json()}
async function cacheAll(){let [a,g,p,m,t]=await Promise.all([api('/areas'),api('/goals'),api('/projects'),api('/milestones'),api('/tasks?per_page=100')]);cache.areas=a.data||a;cache.goals=g.data||g;cache.projects=p.data||p;cache.milestones=m.data||m;cache.tasks=t.data||t}
function pill(v){let s=String(v||'').toLowerCase(),c=['completed','on track','done'].includes(s)?'ok':['blocked','behind','cancelled'].includes(s)?'danger':['waiting','at risk','deferred'].includes(s)?'warn':'';return '<span class="pill '+c+'">'+esc(v||'—')+'</span>'}
function itemRow(x,kind){let title=x.title||x.name||x.intent||'بدون عنوان';return '<div class="row"><div class="rowmain"><div class="rowtitle">'+esc(title)+'</div><div class="rowsub">'+(x.deadline?'مهلت '+fmt(x.deadline):x.target_date?'موعد '+fmt(x.target_date):x.created_at?fmtDT(x.created_at):'')+'</div>'+(x.progress!=null?'<div class="progress"><i style="width:'+Math.min(100,Math.max(0,x.progress))+'%"></i></div>':'')+'</div><div class="rowactions">'+pill(x.status||x.health||x.priority)+'<button class="btn small" onclick="editItem('+x.id+',\''+kind+'\')">ویرایش</button><button class="btn small danger" onclick="deleteItem('+x.id+',\''+kind+'\')">حذف</button></div></div>'}
const schema={
area:{label:'حوزه',ep:'areas',f:[['name','نام','text',1],['type','نوع','text',0],['status','وضعیت','text',0],['sort_order','ترتیب','number',0],['description','توضیحات','textarea',0]]},
goal:{label:'هدف',ep:'goals',f:[['title','عنوان','text',1],['area_id','حوزه','area',0],['status','وضعیت','text',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['progress','پیشرفت','number',0],['start_date','شروع','date',0],['target_date','موعد','date',0],['success_criteria','معیار موفقیت','textarea',0],['description','توضیحات','textarea',0]]},
project:{label:'پروژه',ep:'projects',f:[['title','عنوان','text',1],['goal_id','هدف','goal',0],['status','وضعیت','text',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['progress','پیشرفت','number',0],['estimated_minutes','زمان برآوردی','number',0],['start_date','شروع','date',0],['target_date','موعد','date',0],['description','توضیحات','textarea',0]]},
milestone:{label:'Milestone',ep:'milestones',f:[['title','عنوان','text',1],['project_id','پروژه','project',1],['status','وضعیت','text',0],['weight','وزن','number',0],['progress','پیشرفت','number',0],['target_date','موعد','date',0]]},
task:{label:'Task',ep:'tasks',f:[['title','عنوان','text',1],['description','توضیحات','textarea',0],['area_id','حوزه','area',0],['goal_id','هدف','goal',0],['project_id','پروژه','project',0],['milestone_id','Milestone','milestone',0],['status','وضعیت','status',0],['priority','اولویت P0-P3','priority',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['progress','پیشرفت','number',0],['estimated_minutes','زمان برآوردی','number',0],['deadline','مهلت','datetime-local',0],['planned_start','شروع برنامه','datetime-local',0],['planned_end','پایان برنامه','datetime-local',0],['energy_level','انرژی','number',0],['focus_level','تمرکز','number',0],['failure_reason','علت شکست','text',0]]},
note:{label:'Note',ep:'notes',f:[['title','عنوان','text',1],['content','متن','textarea',1],['area_id','حوزه','area',0],['goal_id','هدف','goal',0],['project_id','پروژه','project',0],['task_id','کار','task',0]]},
decision:{label:'Decision',ep:'decisions',f:[['title','عنوان','text',1],['decision','تصمیم','textarea',1],['rationale','دلیل','textarea',0],['area_id','حوزه','area',0],['decided_at','زمان','datetime-local',1]]},
schedule:{label:'Schedule Block',ep:'schedule-blocks',f:[['task_id','کار','task',0],['starts_at','شروع','datetime-local',1],['ends_at','پایان','datetime-local',1],['status','وضعیت','text',0],['source','منبع','text',0]]},
reminder:{label:'Reminder',ep:'reminders',f:[['task_id','کار','task',0],['type','نوع','text',1],['scheduled_at','زمان','datetime-local',1],['chat_id','Telegram Chat ID','text',1],['message','پیام','textarea',0]]}
};
function options(type){let a={area:cache.areas,goal:cache.goals,project:cache.projects,milestone:cache.milestones,task:cache.tasks}[type]||[];return '<select name="__F"><option value="">—</option>'+a.map(x=>'<option value="'+x.id+'">'+esc(x.title||x.name)+'</option>').join('')+'</select>'}
function field(f){let[n,l,t,req]=f;if(['area','goal','project','milestone','task'].includes(t))return '<div class="field"><label>'+l+'</label>'+options(t).replace('__F',n)+'</div>';if(t==='status')return '<div class="field"><label>'+l+'</label><select name="'+n+'"><option>inbox</option><option>planned</option><option>ready</option><option>in_progress</option><option>blocked</option><option>waiting</option><option>completed</option><option>cancelled</option><option>deferred</option></select></div>';if(t==='priority')return '<div class="field"><label>'+l+'</label><select name="'+n+'"><option value="p0">P0</option><option value="p1">P1</option><option value="p2">P2</option><option value="p3">P3</option></select></div>';return '<div class="field '+(t==='textarea'?'full':'')+'"><label>'+l+'</label>'+(t==='textarea'?'<textarea name="'+n+'" '+(req?'required':'')+'></textarea>':'<input name="'+n+'" type="'+t+'" '+(req?'required':'')+'>')+'</div>'}
async function openCreate(kind){await cacheAll();if(!kind)kind={tasks:'task',goals:'goal',projects:'project',areas:'area',milestones:'milestone',notes:'note',decisions:'decision',calendar:'schedule',reminders:'reminder'}[view]||'task';let s=schema[kind];if(!s)return;modal(s.label+' جدید','<form id=f><div class=formgrid>'+s.f.map(field).join('')+'</div><div class=modalactions><button type=button class=btn onclick=closeModal()>انصراف</button><button class="btn primary">ذخیره</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));Object.keys(d).forEach(k=>{if(d[k]==='')d[k]=null});try{await api('/'+s.ep,{method:'POST',body:JSON.stringify(d)});closeModal();toast('ذخیره شد');loadView(view)}catch(x){toast(x.message)}}}
async function editItem(id,kind){let s=schema[kind];if(!s)return;await cacheAll();let x=await api('/'+s.ep+'/'+id);modal('ویرایش '+s.label,'<form id=f><div class=formgrid>'+s.f.map(field).join('')+'</div><div class=modalactions><button type=button class=btn onclick=closeModal()>انصراف</button><button class="btn primary">ذخیره</button></div></form>');s.f.forEach(([n])=>{let e=document.querySelector('[name="'+n+'"]');if(e&&x[n]!=null)e.value=(e.type==='datetime-local'?String(x[n]).slice(0,16):x[n])});$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));Object.keys(d).forEach(k=>{if(d[k]==='')d[k]=null});try{await api('/'+s.ep+'/'+id,{method:'PUT',body:JSON.stringify(d)});closeModal();toast('به‌روزرسانی شد');loadView(view)}catch(z){toast(z.message)}}}
async function deleteItem(id,kind){let s=schema[kind];if(!s||!confirm('حذف شود؟'))return;try{await api('/'+s.ep+'/'+id,{method:'DELETE'});toast('حذف شد');loadView(view)}catch(e){toast(e.message)}}
function modal(t,b){$('mtitle').textContent=t;$('mbody').innerHTML=b;$('modal').classList.add('show')}function closeModal(){$('modal').classList.remove('show');$('mbody').innerHTML=''}
$('modal').onclick=e=>{if(e.target.id==='modal')closeModal()};
async function loadList(kind,label,ep=kind){let r=await api('/'+ep+(kind==='tasks'?'?per_page=100':'')),a=r.data||r;if(!Array.isArray(a))a=[];$('content').innerHTML='<div class=card><div class=toolbar><input id=q class=search placeholder="جستجو و فیلتر..." oninput=filterList()><button class="btn primary" onclick="openCreate(\''+kind.slice(0,-1)+'\')">＋ '+label+'</button></div><div class=list id=rows>'+a.map(x=>itemRow(x,kind.slice(0,-1))).join('')+(a.length?'':'<div class=empty>موردی وجود ندارد.</div>')+'</div></div>'}
function filterList(){let q=$('q').value.toLowerCase();document.querySelectorAll('#rows .row').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'flex':'none')}
async function today(){let d=await api('/system/dashboard?days=1'),m=d.metrics,t=d.recent_tasks||[];$('content').innerHTML='<div class=cards>'+[['ایجاد شده',m.tasks_created],['تکمیل شده',m.tasks_completed],['نرخ تکمیل',m.completion_rate+'%'],['زمان اجرا',m.execution_minutes+' دقیقه']].map(x=>'<div class=card><div class=muted>'+x[0]+'</div><div class=metric>'+x[1]+'</div></div>').join('')+'</div><div class=grid2><div class=card><div class=head><h2>کارهای اخیر</h2><button class="btn small" onclick="openCreate(\'task\')">＋ کار</button></div><div class=list>'+t.map(x=>itemRow(x,'task')).join('')+'</div></div><div class=card><div class=head><h2>Pending Actions</h2></div><div class=list>'+(d.pending_actions||[]).map(x=>'<div class=row><div><b>'+esc(x.intent)+'</b><div class=rowsub>'+fmtDT(x.created_at)+'</div></div>'+pill(x.status)+'</div>').join('')+'</div></div></div>'}
async function analytics(){let d=await api('/system/dashboard?days=30'),m=d.metrics,gh=m.goal_health||{},fr=m.failure_reasons||{};$('content').innerHTML='<div class=cards>'+Object.entries(m).filter(([k])=>typeof m[k]!=='object').map(([k,v])=>'<div class=card><div class=muted>'+esc(k.replaceAll('_',' '))+'</div><div class=metric>'+esc(v??'—')+'</div></div>').join('')+'</div><div class=grid2><div class=card><div class=head><h2>Goal Health</h2></div><div class=list>'+Object.entries(gh).map(([k,v])=>'<div class=row><b>'+esc(k)+'</b>'+pill(v)+'</div>').join('')+'</div></div><div class=card><div class=head><h2>Failure Reasons</h2></div><div class=list>'+Object.entries(fr).map(([k,v])=>'<div class=row><b>'+esc(k)+'</b><span class=pill>'+esc(v)+'</span></div>').join('')+'</div></div></div>'}
async function reports(){let d=await api('/system/report?period=week'),m=d.metrics,t=d.tasks||[];$('content').innerHTML='<div class=card><div class=head><h2>گزارش هفتگی</h2><div class=actions><button class="btn small" onclick="reportPeriod(\'day\')">روزانه</button><button class="btn small" onclick="reportPeriod(\'week\')">هفتگی</button><button class="btn small" onclick="reportPeriod(\'month\')">ماهانه</button></div></div><div class=statgrid>'+Object.entries(m).filter(([k,v])=>typeof v!=='object').map(([k,v])=>'<div><div class=muted>'+esc(k.replaceAll('_',' '))+'</div><strong>'+esc(v??'—')+'</strong></div>').join('')+'</div><div class=section><div class=tablewrap><table class=table><tr><th>کار</th><th>وضعیت</th><th>اولویت</th><th>پیشرفت</th><th>برآورد/واقعی</th></tr>'+t.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+pill(x.status)+'</td><td>'+pill(x.priority)+'</td><td>'+x.progress+'%</td><td>'+x.estimated_minutes+'/'+x.actual_minutes+'</td></tr>').join('')+'</table></div></div></div>'}
async function reportPeriod(p){let d=await api('/system/report?period='+p),m=d.metrics,t=d.tasks||[];$('content').innerHTML='<div class=card><div class=head><h2>گزارش '+p+'</h2></div><div class=statgrid>'+Object.entries(m).filter(([k,v])=>typeof v!=='object').map(([k,v])=>'<div><div class=muted>'+esc(k.replaceAll('_',' '))+'</div><strong>'+esc(v??'—')+'</strong></div>').join('')+'</div><div class=section><div class=tablewrap><table class=table>'+t.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+pill(x.status)+'</td><td>'+pill(x.priority)+'</td><td>'+x.progress+'%</td></tr>').join('')+'</table></div></div></div>'}
async function searchView(){$('content').innerHTML='<div class=card><div class=head><h2>جستجوی Planner</h2></div><div class=toolbar><input id=globalq class=search placeholder="جستجو در کارها..." onkeydown="if(event.key===\'Enter\')runSearch()"><select id=globalstatus><option value="">همه وضعیت‌ها</option><option>inbox</option><option>planned</option><option>ready</option><option>in_progress</option><option>blocked</option><option>waiting</option><option>completed</option><option>cancelled</option><option>deferred</option></select><button class="btn primary" onclick="runSearch()">جستجو</button></div><div id=searchresults class=list></div></div>'}
async function runSearch(){let q=($('globalq').value||'').trim();if(q.length<2){toast('حداقل ۲ کاراکتر وارد کنید');return}let st=$('globalstatus').value;try{let r=await api('/search?q='+encodeURIComponent(q)+(st?'&status='+encodeURIComponent(st):''));let a=r.tasks||[];$('searchresults').innerHTML=a.map(x=>itemRow(x,'task')).join('')||'<div class=empty>نتیجه‌ای پیدا نشد.</div>'}catch(e){toast(e.message)}}
async function simpleSystem(endpoint,title,create){let r=await api('/system/'+endpoint),a=r.data||r;if(!Array.isArray(a))a=[];$('content').innerHTML='<div class=card><div class=head><h2>'+title+'</h2>'+(create||'')+'</div><div class=list>'+a.map(x=>'<div class=row><div class=rowmain><div class=rowtitle>'+esc(x.title||x.name||x.intent||x.action||x.code||('ID '+x.id))+'</div><div class=rowsub>'+esc(JSON.stringify(x).slice(0,260))+'</div></div>'+pill(x.status||x.preventable||x.severity)+'</div>').join('')+(a.length?'':'<div class=empty>موردی ثبت نشده.</div>')+'</div></div>'}
async function daily(){let r=await api('/system/daily-plans'),a=r.data||[];$('content').innerHTML='<div class=card><div class=head><h2>Daily Plans</h2><button class="btn primary" onclick="createDaily()">＋ برنامه امروز</button></div><div class=list>'+a.map(x=>'<div class=row><div><b>'+esc(x.date)+'</b><div class=rowsub>در دسترس: '+(x.available_minutes||0)+' · برنامه‌ریزی: '+(x.planned_minutes||0)+' · تکمیل: '+(x.completed_minutes||0)+'</div></div><button class="btn small" onclick="editDaily(\''+x.date+'\')">ویرایش</button></div>').join('')+'</div></div>'}
async function createDaily(){modal('Daily Plan','<form id=f><div class=formgrid><div class=field><label>تاریخ</label><input name=date type=date required></div><div class=field><label>دقیقه در دسترس</label><input name=available_minutes type=number required></div><div class=field><label>دقیقه برنامه</label><input name=planned_minutes type=number></div><div class=field><label>دقیقه تکمیل</label><input name=completed_minutes type=number></div><div class=field><label>تمرکز</label><input name=focus_level type=number></div><div class=field><label>انرژی</label><input name=energy_level type=number></div><div class="field full"><label>یادداشت</label><textarea name=notes></textarea></div></div><div class=modalactions><button class="btn primary">ذخیره</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));d.plan_date=d.date;delete d.date;try{await api('/daily-plans',{method:'POST',body:JSON.stringify(d)});closeModal();toast('ثبت شد');daily()}catch(x){toast(x.message)}}}
async function editDaily(date){let x=await api('/daily-plans/'+date);modal('ویرایش Daily Plan','<form id=f><div class=formgrid><div class=field><label>دقیقه در دسترس</label><input name=available_minutes type=number value="'+(x.available_minutes||0)+'"></div><div class=field><label>دقیقه برنامه</label><input name=planned_minutes type=number value="'+(x.planned_minutes||0)+'"></div><div class=field><label>دقیقه تکمیل</label><input name=completed_minutes type=number value="'+(x.completed_minutes||0)+'"></div><div class=field><label>تمرکز</label><input name=focus_level type=number value="'+(x.focus_level||0)+'"></div><div class=field><label>انرژی</label><input name=energy_level type=number value="'+(x.energy_level||0)+'"></div><div class="field full"><label>یادداشت</label><textarea name=notes>'+esc(x.notes||'')+'</textarea></div></div><div class=modalactions><button class="btn primary">ذخیره</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));try{await api('/daily-plans/'+date,{method:'PUT',body:JSON.stringify(d)});closeModal();daily()}catch(z){toast(z.message)}}}
async function editSchedule(id){let r=await api('/schedule-blocks/'+id);modal('ویرایش Schedule Block','<form id=f><div class=formgrid><div class=field><label>شروع</label><input name=starts_at type=datetime-local value="'+String(r.starts_at).slice(0,16)+'"></div><div class=field><label>پایان</label><input name=ends_at type=datetime-local value="'+String(r.ends_at).slice(0,16)+'"></div><div class=field><label>وضعیت</label><input name=status value="'+esc(r.status||'planned')+'"></div></div><div class=modalactions><button class="btn primary">ذخیره</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();try{await api('/schedule-blocks/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e)))});closeModal();calendar()}catch(x){toast(x.message)}}}
async function deleteSchedule(id){if(!confirm('بلوک زمانی حذف شود؟'))return;try{await api('/schedule-blocks/'+id,{method:'DELETE'});toast('حذف شد');calendar() }catch(e){toast(e.message)}}
async function calendar(){await cacheAll();let now=new Date(),start=new Date(now);start.setDate(now.getDate()-((now.getDay()+6)%7));let ds=[];for(let i=0;i<7;i++){let d=new Date(start);d.setDate(start.getDate()+i);ds.push(d)}let bs=await Promise.all(ds.map(d=>api('/schedule-blocks?date='+d.toISOString().slice(0,10)).then(x=>x.data||[]).catch(()=>[])));$('content').innerHTML='<div class=card><div class=head><h2>تقویم هفته</h2><button class="btn primary" onclick="openCreate(\'schedule\')">＋ بلوک زمانی</button></div><div class=calendar>'+ds.map((d,i)=>'<div class=day><b>'+d.toLocaleDateString('fa-IR',{weekday:'short',day:'numeric',month:'short'})+'</b>'+bs[i].map(b=>'<div class=block>'+fmtDT(b.starts_at)+'<br>'+esc(b.task?.title||'Focus')+'<div class=rowactions><button class="btn small" onclick="editSchedule('+b.id+')">ویرایش</button><button class="btn small danger" onclick="deleteSchedule('+b.id+')">×</button></div></div>').join('')+'</div>').join('')+'</div></div>'}
async function aiPlanner(){$('content').innerHTML='<div class=grid2><div class=card><div class=head><h2>AI Planner</h2><span class=muted>AI فقط پیشنهاد می‌دهد؛ Planner Engine اجرا و اعتبارسنجی می‌کند.</span></div><textarea id=aitext style="width:100%;min-height:180px;border:1px solid #d6dce5;border-radius:10px;padding:12px" placeholder="مثلاً: کارهای امروز را بر اساس اولویت و انرژی من برنامه‌ریزی کن"></textarea><div class=modalactions><button class="btn primary" onclick="askAI()">تحلیل و پیشنهاد</button></div></div><div class=card><div class=head><h2>پیشنهادهای اخیر</h2></div><div id=aires class=empty>هنوز پیشنهادی اجرا نشده.</div></div></div>}
async function askAI(){let text=$('aitext').value.trim();if(!text)return;try{let r=await api('/planner/ai-recommendations',{method:'POST',body:JSON.stringify({focus:text})});$('aires').innerHTML='<pre style="white-space:pre-wrap;line-height:1.8">'+esc(JSON.stringify(r,null,2))+'</pre>'}catch(e){toast(e.message)}}
async function execution(){await cacheAll();let rows=[];for(const t of cache.tasks){try{let r=await api('/tasks/'+t.id+'/execution-logs');(r.data||[]).forEach(x=>rows.push({...x,task_title:t.title,task_id:t.id}))}catch{}}rows.sort((a,b)=>new Date(b.started_at)-new Date(a.started_at));$('content').innerHTML='<div class=card><div class=head><h2>Execution Logs</h2><button class="btn primary" onclick="createExecution()">＋ ثبت اجرا</button></div><div class=list>'+rows.map(x=>'<div class=row><div class=rowmain><div class=rowtitle>'+esc(x.task_title)+'</div><div class=rowsub>'+fmtDT(x.started_at)+' · '+(x.duration_minutes||0)+' دقیقه · تمرکز '+(x.focus_level??'—')+' · انرژی '+(x.energy_level??'—')+'</div><div class=rowsub>'+esc(x.result||x.notes||x.blocker||'')+'</div></div><div class=rowactions><button class="btn small" onclick="editExecution('+x.task_id+','+x.id+')">ویرایش</button><button class="btn small danger" onclick="deleteExecution('+x.task_id+','+x.id+')">حذف</button></div></div>').join('')+(rows.length?'':'<div class=empty>هنوز اجرای ثبت‌شده‌ای وجود ندارد.</div>')+'</div></div>'}
async function createExecution(){await cacheAll();modal('ثبت Execution Log','<form id=f><div class=formgrid><div class=field><label>Task</label>'+options('task').replace('__F','task_id')+'</div><div class=field><label>شروع</label><input name=started_at type=datetime-local required></div><div class=field><label>پایان</label><input name=ended_at type=datetime-local></div><div class=field><label>دقیقه</label><input name=duration_minutes type=number min=0></div><div class=field><label>تمرکز</label><input name=focus_level type=number min=0 max=100></div><div class=field><label>انرژی</label><input name=energy_level type=number min=0 max=100></div><div class="field full"><label>نتیجه</label><textarea name=result></textarea></div><div class="field full"><label>یادداشت/مانع</label><textarea name=notes></textarea></div></div><div class=modalactions><button class="btn primary">ثبت</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e)),id=d.task_id;delete d.task_id;try{await api('/tasks/'+id+'/execution-logs',{method:'POST',body:JSON.stringify(d)});closeModal();toast('ثبت شد');execution()}catch(x){toast(x.message)}}}
async function editExecution(taskId,id){let r=await api('/tasks/'+taskId+'/execution-logs'),x=(r.data||[]).find(v=>v.id==id);if(!x)return;modal('ویرایش Execution Log','<form id=f><div class=formgrid><div class=field><label>شروع</label><input name=started_at type=datetime-local value="'+String(x.started_at).slice(0,16)+'"></div><div class=field><label>پایان</label><input name=ended_at type=datetime-local value="'+(x.ended_at?String(x.ended_at).slice(0,16):'')+'"></div><div class=field><label>دقیقه</label><input name=duration_minutes type=number value="'+(x.duration_minutes||0)+'"></div><div class=field><label>تمرکز</label><input name=focus_level type=number value="'+(x.focus_level??'')+'"></div><div class=field><label>انرژی</label><input name=energy_level type=number value="'+(x.energy_level??'')+'"></div><div class="field full"><label>نتیجه</label><textarea name=result>'+esc(x.result||'')+'</textarea></div><div class="field full"><label>یادداشت</label><textarea name=notes>'+esc(x.notes||'')+'</textarea></div></div><div class=modalactions><button class="btn primary">ذخیره</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));try{await api('/tasks/'+taskId+'/execution-logs/'+id,{method:'PUT',body:JSON.stringify(d)});closeModal();execution()}catch(z){toast(z.message)}}}
async function deleteExecution(taskId,id){if(!confirm('این لاگ حذف شود؟'))return;try{await api('/tasks/'+taskId+'/execution-logs/'+id,{method:'DELETE'});toast('حذف شد');execution()}catch(e){toast(e.message)}}
async function failures(){let r=await api('/system/failures'),a=r.data||[];await cacheAll();$('content').innerHTML='<div class=card><div class=head><h2>Failure Reasons</h2><button class="btn primary" onclick="logFailure()">＋ ثبت علت شکست</button></div><div class=list>'+a.map(x=>'<div class=row><div><b>'+esc(x.name||x.code)+'</b><div class=rowsub>قابل پیشگیری: '+esc(x.preventable)+' · شدت: '+esc(x.severity)+'</div></div></div>').join('')+'</div></div>'}
async function logFailure(){await cacheAll();modal('ثبت Failure Reason','<form id=f><div class=formgrid><div class=field><label>Task</label>'+options('task').replace('__F','task_id')+'</div><div class=field><label>علت</label><select name=failure_reason><option>no_time</option><option>poor_estimation</option><option>unexpected_work</option><option>low_energy</option><option>distraction</option><option>too_difficult</option><option>unclear_task</option><option>waiting</option><option>blocked</option><option>wrong_priority</option><option>context_switching</option><option>personal_issue</option><option>technical_problem</option><option>other</option></select></div><div class="field full"><label>توضیح</label><textarea name=description></textarea></div></div><div class=modalactions><button class="btn primary">ثبت</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e)),id=d.task_id;delete d.task_id;try{await api('/tasks/'+id,{method:'PUT',body:JSON.stringify({failure_reason:d.failure_reason,description:d.description,status:'blocked'})});closeModal();toast('علت شکست ثبت شد');failures()}catch(x){toast(x.message)}}}
async function dependencies(){await cacheAll();let rows=[];for(const t of cache.tasks){try{let r=await api('/tasks/'+t.id+'/dependencies');(r||[]).forEach(x=>rows.push({...x,task_title:t.title,task_id:t.id}))}catch{}}$('content').innerHTML='<div class=card><div class=head><h2>Dependencies</h2><button class="btn primary" onclick="addDependency()">＋ Dependency</button></div><div class=list>'+rows.map(x=>'<div class=row><div><b>'+esc(x.task_title)+'</b><div class=rowsub>'+esc(x.type)+' ← '+esc(x.depends_on?.title||x.dependsOn?.title||'Task #'+x.depends_on_task_id)+'</div></div><button class="btn small danger" onclick="deleteDependency('+x.task_id+','+x.id+')">حذف</button></div>').join('')+(rows.length?'':'<div class=empty>Dependency ثبت نشده است.</div>')+'</div></div>'}
async function deleteDependency(taskId,id){if(!confirm('این dependency حذف شود؟'))return;try{await api('/tasks/'+taskId+'/dependencies/'+id,{method:'DELETE'});toast('حذف شد');dependencies()}catch(e){toast(e.message)}}
async function addDependency(){await cacheAll();modal('Dependency','<form id=f><div class=formgrid><div class=field><label>Task</label>'+options('task').replace('__F','task_id')+'</div><div class=field><label>Task وابسته</label>'+options('task').replace('__F','depends_on_task_id')+'</div><div class=field><label>نوع</label><select name=type><option>blocks</option><option>requires</option><option>related</option></select></div></div><div class=modalactions><button class="btn primary">ثبت</button></div></form>');$('f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e));try{await api('/tasks/'+d.task_id+'/dependencies',{method:'POST',body:JSON.stringify({depends_on_task_id:d.depends_on_task_id,type:d.type})});closeModal();toast('ثبت شد')}catch(x){toast(x.message)}}}
async function cancelReminder(id){if(!confirm('یادآور لغو شود؟'))return;try{await api('/reminders/'+id+'/cancel',{method:'POST'});toast('لغو شد');loadView('reminders')}catch(e){toast(e.message)}}
async function loadView(v){view=v;$('title').textContent={today:'امروز',tasks:'کارها',inbox:'Inbox',search:'جستجو',areas:'حوزه‌ها',goals:'اهداف',projects:'پروژه‌ها',milestones:'Milestones',daily:'Daily Plan',calendar:'تقویم',execution:'Execution Logs',dependencies:'Dependencies',reminders:'یادآورها',failures:'Failure Reasons',reviews:'Reviews',analytics:'Analytics',reports:'Reports',notes:'Notes',decisions:'Decisions',ai:'AI Interactions', 'ai-planner':'AI Planner',pending:'Pending Actions',activity:'Activity Logs'}[v]||v;try{
if(v==='today'||v==='inbox')return today();if(v==='search')return searchView();if(v==='ai-planner')return aiPlanner();if(v==='analytics')return analytics();if(v==='reports')return reports();if(v==='daily')return daily();if(v==='calendar')return calendar();if(v==='dependencies')return dependencies();
if(v==='execution')return execution();if(v==='failures')return failures();if(v==='ai')return simpleSystem('ai-interactions','AI Interactions');if(v==='pending')return simpleSystem('pending-actions','Pending Actions');if(v==='activity')return simpleSystem('activity','Activity Logs');
if(v==='reviews'){let r=await api('/reviews'),a=r.data||[];$('content').innerHTML='<div class=card><div class=head><h2>Reviews</h2><button class="btn primary" onclick="generateReview()">＋ Review</button></div><div class=list>'+a.map(x=>'<div class=row><div><b>'+esc(x.type)+'</b><div class=rowsub>'+fmt(x.period_start)+' تا '+fmt(x.period_end)+' · '+esc(x.summary||'')+'</div></div></div>').join('')+'</div></div>';return}
if(v==='notes')return loadList('notes','یادداشت');if(v==='decisions')return loadList('decisions','تصمیم');
let map={tasks:['tasks','کارها'],goals:['goals','اهداف'],projects:['projects','پروژه‌ها'],areas:['areas','حوزه‌ها'],milestones:['milestones','Milestones'],reminders:['reminders','یادآورها']};return loadList(map[v][0],map[v][1]);
}catch(e){$('content').innerHTML='<div class=card><div style="color:#b42318">'+esc(e.message)+'</div></div>'}}
async function generateReview(){try{await api('/reviews/generate',{method:'POST',body:JSON.stringify({type:'weekly'})});toast('Review تولید شد');loadView('reviews')}catch(e){toast(e.message)}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');loadView(b.dataset.view)});
loadView('today');
</script></body></html>